const navItems=[['home','Übersicht','home'],['checklist','Kurs-Checkliste','exam'],['learn','Lernzettel','learn'],['methods','Handlungsergebnisse','learn'],['cards','Karteikarten','cards'],['quiz','Wissensquiz','quiz'],['calc','Rechentrainer','calc'],['schemes','Kalkulationsschemata','calc'],['proposal','Vorabi-Vorschlag','exam'],['exam','Klausurtraining','exam'],['plan','Dein Lernplan','plan'],['progress','Fortschritt','progress']];
const defaultState=()=>({...learningDefaults(),version:1,course:courseMode,view:generalView?'general':'study',read:[],known:[],answers:{},calculations:[],days:[],checks:[],examDate:'2026-11-10',exam:null,proposal:proposalDefault()});
function validateState(raw){
 if(!raw||raw.version!==1) throw Error('Nicht unterstütztes Fortschrittsformat.');
 if(raw.course&&raw.course!==courseMode)throw Error('Dieser Fortschritt gehört zum anderen Kurs. Wechsle vor dem Import in den passenden Kurs.');
 if(!raw.course&&courseMode!=='main')throw Error('Ein älterer Export ohne Kursangabe gehört zu „Mein Kurs“.');
 if((raw.view||'study')!==(generalView?'general':'study'))throw Error('Dieser Fortschritt gehört zur anderen Ansicht. Wechsle vor dem Import in die passende Ansicht.');
 const s=defaultState();Object.assign(s,validateLearning(raw,activeCourse));
 s.proposal=generalView?proposalDefault():validateProposal(raw.proposal);
 s.read=[...new Set((Array.isArray(raw.read)?raw.read:[]).filter(x=>lessons.some(l=>l.id===x)))];
 s.known=[...new Set((Array.isArray(raw.known)?raw.known:[]).filter(x=>cards.some(c=>c.id===x)))];
 s.days=[...new Set((Array.isArray(raw.days)?raw.days:[]).filter(x=>Number.isInteger(x)&&x>=0&&x<plan.length))];
 s.checks=[...new Set((Array.isArray(raw.checks)?raw.checks:[]).filter(id=>activeCourse.checklist.some(c=>c.id===id)))];
 if(raw.answers&&typeof raw.answers==='object') for(const question of quiz){const a=raw.answers[question.id];if(a&&typeof a==='object'&&Number.isInteger(a.total)&&Number.isInteger(a.right)&&a.total>0&&a.total<100000&&a.right>=0&&a.right<=a.total)s.answers[question.id]={total:a.total,right:a.right,last:!!a.last};}
 s.calculations=(Array.isArray(raw.calculations)?raw.calculations:[]).filter(x=>typeof x==='string'&&/^(kalkulation|breakeven|bestellmenge|bedarf|bezug|makebuy|vorwaerts|rueckwaerts|kennzahlen|lagerkritisch|deckungsbeitrag)-[0-2]$/.test(x)).filter((x,i,a)=>a.indexOf(x)===i);
 if(typeof raw.examDate==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(raw.examDate)&&Number.isFinite(new Date(raw.examDate+'T12:00:00').getTime()))s.examDate=raw.examDate;
 if(raw.exam&&typeof raw.exam==='object'){
  const e=raw.exam;
  if(e.revision==='2026-11-07-'+courseMode&&['running','paused','finished'].includes(e.status)&&Number.isFinite(e.remaining)&&e.remaining>=0&&e.remaining<=5100){
   const scores={};for(const t of examTasks)if(Number.isFinite(e.scores?.[t.id])&&e.scores[t.id]>=0&&e.scores[t.id]<=t.points)scores[t.id]=e.scores[t.id];
   s.exam={revision:e.revision,status:e.status,remaining:e.remaining,deadline:typeof e.deadline==='number'&&Number.isFinite(e.deadline)?e.deadline:null,scores};
  }
 }
 return s;
}
let storageOK=true,state;
try{const raw=localStorage.getItem(activeCourse.storageKey);state=raw?validateState(JSON.parse(raw)):defaultState();}catch{state=defaultState();storageOK=false;}
function save(){try{localStorage.setItem(activeCourse.storageKey,JSON.stringify(state));return true;}catch{if(storageOK)toast('Speichern ist blockiert. Exportiere deinen Fortschritt zur Sicherung.');storageOK=false;return false;}}
function switchCourse(id){
 if(id===courseMode)return;save();courseMode=id;activeCourse=(generalView?generalCourses:courses)[id];
 ({groups,lessons,cards,quiz,plan,examTasks,exerciseTypes,makeExercise}=activeCourse);
 try{localStorage.setItem('brc-course-v1',id);const raw=localStorage.getItem(activeCourse.storageKey);state=raw?validateState(JSON.parse(raw)):defaultState();storageOK=true;}catch{state=defaultState();storageOK=false;}
 cardSession=null;quizSession=null;exerciseSession=initialExercise();
 if(location.hash==='#home')render();else location.hash='home';
 toast(id==='glaeser'?'Frau Gläser: eigene Checkliste und blauer Lernbereich.':'Zurück in deinem bisherigen Kurs.');
}
function toggleGeneralView(){
 save();clearTimeout(toastTimer);$('#toast').textContent='';$('#toast').classList.remove('show');generalView=!generalView;
 try{localStorage.setItem('brc-general-view-v1',generalView?'on':'off');}catch{}
 activeCourse=(generalView?generalCourses:courses)[courseMode];
 ({groups,lessons,cards,quiz,plan,examTasks,exerciseTypes,makeExercise}=activeCourse);
 try{const raw=localStorage.getItem(activeCourse.storageKey);state=raw?validateState(JSON.parse(raw)):defaultState();storageOK=true;}catch{state=defaultState();storageOK=false;}
 cardSession=null;quizSession=null;exerciseSession=initialExercise();
 if(location.hash==='#home')render();else location.hash='home';
}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const fmt=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(n);
const group=id=>groups.find(g=>g.id===id);
const lesson=id=>lessons.find(l=>l.id===id);
const pct=(a,b)=>b?Math.round(a/b*100):0;
const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;};
const progress=(n,total)=>`<div class="progress-track" role="progressbar" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${total}" aria-label="Fortschritt"><span style="width:${pct(n,total)}%"></span></div>`;
function heading(title,subtitle,right=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${right}</div>`;}
function dateLabel(){return new Date(state.examDate+'T12:00:00').toLocaleDateString('de-DE',{day:'2-digit',month:'long',year:'numeric'});}
function daysLeft(){const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),then=new Date(state.examDate+'T00:00:00');return Math.round((then-today)/86400000);}
function datePill(){const days=daysLeft();return `<a href="#progress" class="date-pill">◷ ${days>0?`Noch ${days} ${days===1?'Tag':'Tage'}`:days===0?'Heute ist dein Prüfungstag':'Dein Lerntempo zählt'} · ${esc(dateLabel())}</a>`;}
function lessonCard(l){const g=group(l.group),done=state.read.includes(l.id);return `<a class="lesson-card" href="#lesson/${l.id}"><span class="lesson-symbol ${g.color}" aria-hidden="true">${g.symbol}</span><div><small>${g.name} · ${l.minutes} Min.</small><h3>${l.title}</h3><p>${l.intro}</p>${done?'<div class="done">✓ Als gelesen markiert</div>':`<div class="done muted">${l.tag} <span aria-hidden="true">↗</span></div>`}</div></a>`;}
function activeGroupOptions(selected='all'){return `<option value="all" ${selected==='all'?'selected':''}>Alle Themenbereiche</option>${groups.map(g=>`<option value="${g.id}" ${selected===g.id?'selected':''}>${g.name}</option>`).join('')}`;}
function subsetOptions(selected='all'){return activeGroupOptions(selected)+`<optgroup label="Einzelne Lernzettel">${lessons.map(l=>`<option value="${l.id}" ${selected===l.id?'selected':''}>${l.title}</option>`).join('')}</optgroup>`;}
const matches=(x,filter)=>filter==='all'||x.group===filter||x.lesson===filter;
const quizPool=filter=>filter==='errors'?quiz.filter(q=>state.answers[q.id]&&!state.answers[q.id].last):filter==='due'?dueQuestions(activeCourse,state):quiz.filter(q=>matches(q,filter));
const cardPool=filter=>filter==='due'?dueCards(activeCourse,state):cards.filter(c=>matches(c,filter));
