 document.body.dataset.general=String(generalView);$('#general-view').setAttribute('aria-pressed',String(generalView));
 document.querySelector('meta[name="theme-color"]').content=courseMode==='glaeser'?'#63bcff':'#101210';
 document.querySelectorAll('[data-course-button]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.courseButton===courseMode)));
 const active=route==='lesson'?'learn':route;
 $('#nav').innerHTML=navItems.filter(([id])=>id!=='proposal'||(courseMode==='main'&&!generalView)).map(([id,name,symbol])=>`<a href="#${id}" ${active===id?'class="active" aria-current="page"':''}>${icon(symbol)}<span>${name}</span>${id==='learn'?`<span class="nav-badge">${lessons.length}</span>`:''}</a>`).join('');
 $('#breadcrumb').textContent=activeCourse.label+' / '+(route==='lesson'?(lesson(arg)?.title||'Lernzettel'):navItems.find(x=>x[0]===route)?.[1]||'Über die Lernwelt');
 const routes={home:renderHome,schemes:()=>renderCalculationSchemes($('#main'),arg,exerciseTypes.map(([id])=>id)),methods:()=>renderMethods($('#main'),arg),checklist:renderChecklist,learn:()=>renderLearn(arg),lesson:()=>renderLesson(arg),cards:()=>renderCards(arg),quiz:()=>renderQuiz(arg),calc:()=>renderCalc(arg),proposal:()=>renderProposal(arg),exam:renderExam,plan:renderPlan,progress:renderProgress,info:renderInfo};
 $('#main').className='page-enter';(routes[route]||renderHome)();
 if(route==='info'&&!generalView)$('#main .reader').insertAdjacentHTML('afterbegin',`<div class="callout scope-note"><strong>Aktiv: ${esc(activeCourse.label)}</strong>${esc(activeCourse.source)}. ${courseMode==='glaeser'?'Dieser Kurs verwendet die zusätzliche Checkliste; die optimale Bestellmenge wird hier tabellarisch, rechnerisch und grafisch behandelt.':'Dieser Kurs folgt dem Vorschlag mit aktueller Lehrerergänzung. Die optimale Bestellmenge wird ohne Rechnung und Grafik behandelt. Die Buchseiten 65–68 und 71–72 sind eingearbeitet: Marktsegmentierung, fünf Marktbearbeitungsstrategien und die Ansoff-Matrix. Das Fitnessstudio-Beispiel und die Übersicht zur Marktabdeckung sind ergänzt.'} Lernfortschritt, Checkliste und Generalprobe werden pro Kurs getrennt gespeichert. Die Quellenaufnahmen werden nicht veröffentlicht.</div>`);
 document.title=(route==='lesson'?lesson(arg)?.title:navItems.find(x=>x[0]===route)?.[1]||'Über die Lernwelt')+' · '+activeCourse.label+' · BRC Lernwelt';
 closeMenu();
 window.scrollTo({top:0,behavior:'instant'});
 $('#main').focus({preventScroll:true});
 initExperience();
