function renderEvidencePanel(){
 const p=learningSummary(activeCourse,state);
 return `<section class="learning-evidence" aria-label="Dein Lernstand getrennt nach Nachweis"><div><small>GELESEN · SELBST MARKIERT</small><strong>${p.read} / ${lessons.length}</strong><p>Lernzettel durchgesehen</p></div><div><small>SELBST EINGESCHÄTZT</small><strong>${p.assessed} / ${lessons.length}</strong><p>Alle Lernziele dieser Themen selbst abgehakt</p></div><div><small>ÜBUNGSERFOLG</small><strong>${p.verified} / ${lessons.length}</strong><p>Alle Quizfragen eines Themas zuletzt richtig (mindestens zwei) oder eine Rechnung ohne geöffnete Lösung gelöst.</p></div><p class="evidence-note">Momentaufnahme, keine Garantie für sichere Beherrschung. Quiz und Rechnung sind überprüfte Übungen; freie Texte und Karten bleiben Selbsteinschätzung. Ältere Rechnungsabschlüsse ohne Nachweis zählen hier noch nicht.</p></section>`;
}
function renderDailyPanel(){
 const p=buildDailyPlan(activeCourse,state),e=learningSummary(activeCourse,state);
 return `<section class="daily-learning"><div class="daily-heading"><div><span class="eyebrow acid">DEIN NÄCHSTER SCHRITT</span><h2>Dein Tagesplan.</h2><p>${p.days>=0&&p.days<=3?'Kurze Lernblöcke vor deinem Prüfungstermin.':'Deine nächste Lernrunde.'} Rund ${p.minutes} Minuten · Empfehlungen passen sich deinem Lernstand an.</p></div><a class="btn secondary small" href="#progress">Lernstand ansehen ↗</a></div><ol>${p.items.map((item,i)=>`<li><span>0${i+1}</span><div><h3>${esc(item.title)}</h3><p>${esc(item.reason)} · ca. ${item.minutes} Min.</p></div><a class="btn ${i?'secondary':''} small" href="${item.href}" aria-label="${esc(item.title)} starten">${i?'Öffnen':'Jetzt starten'} ↗</a></li>`).join('')}</ol><p class="daily-summary">${e.read} Themen als gelesen markiert · ${e.assessed} selbst eingeschätzt · ${e.verified} mit Übungserfolg</p><div class="daily-actions"><a href="#quiz/errors">Offene Quizfehler</a><a href="#quiz/due">Fällige Quizfragen</a><a href="#cards/due">Fällige Karten</a></div></section>`;
}
